create schema auth;
create role anon nologin;
create role authenticated nologin; create role service_role nologin bypassrls;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create table public.profiles(id uuid primary key references auth.users(id), full_name text, role text, school_id uuid, class_grade text, section text);
create table public.students(id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id), grade text);
create table public.parent_students(id uuid primary key default gen_random_uuid(), parent_id uuid, student_id uuid);
create table public.books(id bigint generated by default as identity primary key, book_name text, class_name text, subject text, curriculum text, school_id uuid, is_active boolean default true);
create table public.units(id bigint generated by default as identity primary key, book_id bigint references public.books(id), unit_name text);
create table public.curriculum_chapters(id bigint generated by default as identity primary key, unit_id bigint references public.units(id), chapter_name text);
create table public.topics(id bigint generated by default as identity primary key, chapter_id bigint references public.curriculum_chapters(id), topic_name text);
create table public.subtopics(id bigint generated by default as identity primary key, topic_id bigint references public.topics(id), subtopic_name text);
create table public.learning_objectives(id bigint generated by default as identity primary key, subtopic_id bigint references public.subtopics(id));
create table public.student_mastery(id uuid primary key default gen_random_uuid(), student_id uuid, learning_objective_id bigint, p_mastery numeric default 0.3);
create table public.mastery_log(student_id uuid, lo bigint, correct boolean, source text, source_id uuid);
create function public.record_mastery_evidence(p_student_id uuid, p_learning_objective_id bigint, p_is_correct boolean, p_source text, p_source_id uuid default null) returns table(a numeric, b numeric) language plpgsql as $$ begin insert into mastery_log values (p_student_id,p_learning_objective_id,p_is_correct,p_source,p_source_id); return query select 0.3::numeric,0.4::numeric; end $$;
create table public.question_bank(id uuid primary key default gen_random_uuid(), learning_objective_id bigint, subtopic_id bigint, stem text, options jsonb, correct_option text, explanation text, status text default 'draft', irt_b numeric default 0, review_flag text);
create table public.governance_notifications(id uuid primary key default gen_random_uuid(), user_id uuid, event_type text, title text, message text, reference_id uuid, reference_type text);
grant usage on schema public, auth to authenticated, service_role;
grant execute on function auth.uid() to authenticated, service_role;
